import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Inscription","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/inscription.md","filePath":"en/guide/professions/inscription.md"}'),r={name:"en/guide/professions/inscription.md"};function o(s,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="inscription" tabindex="-1">Inscription <a class="header-anchor" href="#inscription" aria-label="Permalink to &quot;Inscription&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> <strong>Implementation:</strong> this redesign is not established as implemented. <strong>Availability:</strong> not established as live. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-09 against Batch 04.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Inscription records, preserves and modifies magical knowledge.</li><li>Scrolls, variants and organized grimoires provide tactical and economic roles.</li><li>Execution, learned methods and specialization differ; physical magical products retain loot risk.</li></ul><p><a href="/Syrolands-Public/en/game-design/professions/inscription.html">Full design specification</a></p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Proposed role / boundary</th></tr></thead><tbody><tr><td>What it does</td><td>Inscription is proposed as magical engineering: recording, preserving and carefully changing written magical structures. Scrolls are one product; glyphs, variant notation, indexed grimoires, wards and ritual diagrams are other candidate specializations.</td></tr><tr><td>Skill and identity</td><td>Skill supports execution, learned techniques/schools supply methods and profession paths express specialization. A scribe might become known for combat scrolls, rare variants or well-organized books. Technique names and ward/ritual scope are not final.</td></tr><tr><td>Learning and production</td><td>Magery, known patterns, reagents and Alchemy can interact with the craft. Buying an ordinary casting scroll would not buy permanent knowledge; copying and player teaching need explicit rules. Secrets, production, commissions and reputation follow the <a href="/Syrolands-Public/en/guide/professions/overview.html">shared profession proposal</a>.</td></tr><tr><td>Tactical value and risk</td><td>Prepared scrolls may offer faster emergency reference at consumable cost. Rare physical grimoires and reagents remain exposed to loot risk; workmanship does not grant insurance. <a href="/Syrolands-Public/en/guide/magic/spellbooks-scrolls-and-reagents.html">Books and materials</a> · <a href="/Syrolands-Public/en/guide/magic/variants-and-glyphs.html">Variants</a>.</td></tr></tbody></table>',7)])])}const m=a(r,[["render",o]]);export{h as __pageData,m as default};
